--
-- Name: command_core(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_core(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  actor_prof private.profiles;
  result jsonb;
  order_rec private.orders;
begin
  select * into actor_prof from private.profiles where id = p_actor;

  -- If operation is order_create or order_update, capture creator snapshots
  if p_operation in ('order_create', 'order_update') then
    result := private.command_core_before_staff_immutability(p_operation, p_payload, p_actor);
    update private.orders
    set
      created_by_name = coalesce(created_by_name, actor_prof.full_name, 'Staff Member'),
      created_by_email = coalesce(created_by_email, actor_prof.email, 'staff@smartdine.pk')
    where id = (result->>'id')::uuid;
    return private.order_json((result->>'id')::uuid, actor_prof.role = 'manager');
  end if;

  -- If operation is order_transition to preparing/ready, capture kitchen chef snapshot
  if p_operation = 'order_transition' and p_payload->>'status' in ('preparing', 'ready') then
    result := private.command_core_before_staff_immutability(p_operation, p_payload, p_actor);
    update private.orders
    set
      prepared_by = coalesce(prepared_by, p_actor),
      prepared_by_name = coalesce(prepared_by_name, actor_prof.full_name, 'Kitchen Staff'),
      prepared_by_email = coalesce(prepared_by_email, actor_prof.email, 'kitchen@smartdine.pk'),
      prepared_at = coalesce(prepared_at, now())
    where id = (p_payload->>'id')::uuid;
    return private.order_json((p_payload->>'id')::uuid, actor_prof.role = 'manager');
  end if;

  -- If operation is order_pay, capture cashier snapshot
  if p_operation = 'order_pay' then
    result := private.command_core_before_staff_immutability(p_operation, p_payload, p_actor);
    update private.orders
    set
      paid_by = p_actor,
      paid_by_name = coalesce(actor_prof.full_name, 'Cashier Staff'),
      paid_by_email = coalesce(actor_prof.email, 'cashier@smartdine.pk')
    where id = (p_payload->>'id')::uuid;
    return result;
  end if;

  return private.command_core_before_staff_immutability(p_operation, p_payload, p_actor);
end $$;


ALTER FUNCTION private.command_core(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: command_core_before_cashier(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_core_before_cashier(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare ingredient uuid; product uuid; q numeric; cost numeric; ing private.ingredients; result jsonb;
begin
 if p_operation='inventory_record' and exists(select 1 from private.menu_items where stock_ingredient_id=(p_payload->>'ingredient_id')::uuid) and (p_payload->>'quantity')::numeric<>trunc((p_payload->>'quantity')::numeric) then
  raise exception using errcode='22023',message='Bottle quantities must be whole numbers';
 end if;
 if p_operation='ingredient_update' and exists(select 1 from private.menu_items where stock_ingredient_id=(p_payload->>'id')::uuid) and p_payload->>'unit'<>'piece' then
  raise exception using errcode='22023',message='Drinks are counted in pieces';
 end if;
 if p_operation in ('stock_product_create','stock_receive','stock_remove') then
  if private.require_actor(true)<>p_actor then raise exception using errcode='42501',message='Manager required';end if;
  q:=(p_payload->>'quantity')::numeric;
  if q is null or q<0 or q<>trunc(q) or q>1000000 or (p_operation<>'stock_product_create' and q=0) then raise exception using errcode='22023',message='Enter a whole-number quantity';end if;
  if p_operation='stock_product_create' then
   if coalesce((p_payload->>'selling_price')::numeric,0)<=0 then raise exception using errcode='22023',message='Selling price must be positive';end if;
   insert into private.ingredients(name,unit,reorder_level) values(p_payload->>'name','piece',coalesce((p_payload->>'reorder_level')::integer,5)) returning id into ingredient;
   insert into private.menu_items(name,category,selling_price,stock_ingredient_id) values(p_payload->>'name','Drinks',(p_payload->>'selling_price')::numeric,ingredient) returning id into product;
   cost:=coalesce((p_payload->>'unit_cost')::numeric,0);
  else
   select * into ing from private.ingredients where id=(p_payload->>'id')::uuid for update;
   if not found or not exists(select 1 from private.menu_items where stock_ingredient_id=ing.id and deleted_at is null) then raise exception using errcode='P0002',message='Stock item not found';end if;
   ingredient:=ing.id;cost:=coalesce((p_payload->>'unit_cost')::numeric,ing.average_unit_cost);
  end if;
  if q>0 then
   perform private.command_core_before_simple_stock('inventory_record',jsonb_build_object('ingredient_id',ingredient,'kind',case when p_operation='stock_remove' then 'wastage' else 'purchase' end,'quantity',q,'reason',coalesce(nullif(p_payload->>'reason',''),case when p_operation='stock_remove' then 'Damaged or missing bottles' else 'Stock received' end)) || case when p_operation='stock_remove' then '{}'::jsonb else jsonb_build_object('unit_cost',cost) end,p_actor);
  end if;
  result:=jsonb_build_object('id',ingredient,'menu_item_id',product,'status','saved');
  perform private.audit(p_actor,p_operation,'ingredients',ingredient,null,result);
  return result;
 end if;
 return private.command_core_before_simple_stock(p_operation,p_payload,p_actor);
end $$;


ALTER FUNCTION private.command_core_before_cashier(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: command_core_before_floor_tables(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_core_before_floor_tables(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  prof private.profiles;
  o private.orders;
  total numeric;
  received numeric;
  result jsonb;
begin
  if private.require_actor(false) <> p_actor then
    raise exception using errcode = '42501', message = 'Actor mismatch';
  end if;
  select * into prof from private.profiles where id = p_actor;
  if prof.role = 'staff'
     and prof.staff_type = 'cashier'
     and p_operation not in ('order_pay', 'review_token_create') then
    raise exception using errcode = '42501', message = 'Cashier access is limited to payments and receipt review links';
  end if;
  if p_operation = 'order_pay' then
    if prof.role <> 'manager' and prof.staff_type <> 'cashier' then
      raise exception using errcode = '42501', message = 'Cashier access required';
    end if;
    select * into o from private.orders where id = (p_payload->>'id')::uuid for update;
    if not found then
      raise exception using errcode = 'P0002', message = 'Bill not found';
    end if;
    perform private.expect_version(o.version, (p_payload->>'expected_version')::integer);
    if o.status <> 'ready' then
      raise exception using errcode = '40001', message = 'Only ready, unpaid orders can be paid';
    end if;
    total := (private.order_json(o.id, false)->>'total')::numeric;
    received := (p_payload->>'cash_received')::numeric;
    if received is null or received < total or received <> round(received, 2) then
      raise exception using errcode = '22023', message = 'Cash received must cover the full bill';
    end if;
    update private.orders
    set paid_by = p_actor, cash_received = received, change_given = received - total
    where id = o.id;
    result := private.command_core_before_cashier(
      'order_transition',
      jsonb_build_object('id', o.id, 'expected_version', o.version, 'status', 'completed'),
      p_actor
    );
    perform private.audit(
      p_actor,
      'order_paid',
      'orders',
      o.id,
      null,
      jsonb_build_object('total', total, 'cash_received', received, 'change_given', received - total)
    );
    return result;
  end if;
  return private.command_core_before_cashier(p_operation, p_payload, p_actor);
end;
$$;


ALTER FUNCTION private.command_core_before_floor_tables(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: command_core_before_menu_delete(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.command_core_before_menu_delete(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
#variable_conflict use_variable
declare actor uuid:=private.require_actor(false); id uuid:=(p_payload->>'id')::uuid; expected integer:=(p_payload->>'expected_version')::int;
 mgr boolean; m private.menu_items; ing private.ingredients; o private.orders; ex private.expenses; prof private.profiles; rec private.recommendations;
 before_data jsonb; item record; qty numeric; cost numeric; delta numeric; token text; result jsonb; newstatus text; target uuid;
begin
 if actor<>p_actor then raise exception using errcode='42501',message='Actor mismatch'; end if;
 select role='manager' into mgr from private.profiles where profiles.id=actor;
 if p_operation in ('menu_create','menu_update','recipe_set','ingredient_create','ingredient_update','expense_void','user_update','recommendation_create','recommendation_approve','recommendation_reject','recommendation_apply') then perform private.require_actor(true); end if;
 if p_operation='menu_create' then
 insert into private.menu_items(name,category,selling_price,packaging_cost,is_active) values(p_payload->>'name',coalesce(p_payload->>'category','General'),(p_payload->>'selling_price')::numeric,coalesce((p_payload->>'packaging_cost')::numeric,0),coalesce((p_payload->>'is_active')::boolean,true)) returning menu_items.id into id;
 result:=private.read_core('menu',jsonb_build_object('id',id));
 elsif p_operation='menu_update' then
 select * into m from private.menu_items where menu_items.id=id for update; if not found then raise exception using errcode='P0002',message='Menu item not found'; end if;
 perform private.expect_version(m.version,expected); before_data:=to_jsonb(m);
 update private.menu_items set name=coalesce(p_payload->>'name',name),category=coalesce(p_payload->>'category',category),selling_price=coalesce((p_payload->>'selling_price')::numeric,selling_price),packaging_cost=coalesce((p_payload->>'packaging_cost')::numeric,packaging_cost),is_active=coalesce((p_payload->>'is_active')::boolean,is_active),version=version+1,updated_at=now() where menu_items.id=id;
 result:=private.read_core('menu',jsonb_build_object('id',id));
 elsif p_operation='recipe_set' then
 perform private.set_recipe(id,p_payload->'ingredients',expected,actor); return private.read_core('recipes',jsonb_build_object('id',id));
 elsif p_operation='ingredient_create' then
 insert into private.ingredients(name,unit,reorder_level) values(p_payload->>'name',p_payload->>'unit',coalesce((p_payload->>'reorder_level')::numeric,0)) returning ingredients.id into id;
 result:=private.read_core('inventory',jsonb_build_object('id',id));
 elsif p_operation='ingredient_update' then
 select * into ing from private.ingredients where ingredients.id=id for update; if not found then raise exception using errcode='P0002',message='Ingredient not found'; end if;
 perform private.expect_version(ing.version,expected); before_data:=to_jsonb(ing);
 if p_payload ? 'unit' and p_payload->>'unit'<>ing.unit then raise exception using errcode='22023',message='Canonical unit is immutable; create a new ingredient'; end if;
 update private.ingredients set name=coalesce(p_payload->>'name',name),reorder_level=coalesce((p_payload->>'reorder_level')::numeric,reorder_level),is_active=coalesce((p_payload->>'is_active')::boolean,is_active),version=version+1,updated_at=now() where ingredients.id=id;
 result:=private.read_core('inventory',jsonb_build_object('id',id));
 elsif p_operation='inventory_record' then
 select * into ing from private.ingredients where ingredients.id=(p_payload->>'ingredient_id')::uuid for update;
 if not found then raise exception using errcode='P0002',message='Ingredient not found'; end if;
 qty:=(p_payload->>'quantity')::numeric;
 if qty is null or qty=0 or length(btrim(coalesce(p_payload->>'reason','')))=0 then raise exception using errcode='22023',message='Nonzero quantity and reason required'; end if;
 before_data:=to_jsonb(ing); cost:=ing.average_unit_cost;
 if p_payload->>'kind'='purchase' then
 if qty<=0 or p_payload->>'unit_cost' is null or (p_payload->>'unit_cost')::numeric<0 then raise exception using errcode='22023',message='Purchase requires positive quantity and nonnegative unit_cost'; end if;
 cost:=(p_payload->>'unit_cost')::numeric; delta:=qty;
 update private.ingredients set average_unit_cost=(stock_quantity*average_unit_cost+qty*cost)/(stock_quantity+qty) where ingredients.id=ing.id;
 elsif p_payload->>'kind'='wastage' then
 if qty<=0 then raise exception using errcode='22023',message='Wastage quantity must be positive'; end if; delta:=-qty;
 elsif p_payload->>'kind'='adjustment' then delta:=qty;
 else raise exception using errcode='22023',message='Invalid inventory transaction kind'; end if;
 if ing.stock_quantity+delta<0 then raise exception using errcode='40001',message='Insufficient stock'; end if;
 update private.ingredients set stock_quantity=stock_quantity+delta,version=version+1,updated_at=now() where ingredients.id=ing.id;
 insert into private.inventory_transactions(ingredient_id,kind,quantity,unit_cost,value,reason,created_by) values(ing.id,p_payload->>'kind',delta,cost,delta*cost,p_payload->>'reason',actor) returning inventory_transactions.id into id;
 result:=private.read_core('inventory_transactions',jsonb_build_object('id',id));
 elsif p_operation in ('order_create','order_update') then
 if p_operation='order_create' then
 insert into private.orders(discount,platform_fee,delivery_cost,tax,notes,created_by) values(coalesce((p_payload->>'discount')::numeric,0),coalesce((p_payload->>'platform_fee')::numeric,0),coalesce((p_payload->>'delivery_cost')::numeric,0),coalesce((p_payload->>'tax')::numeric,0),coalesce(p_payload->>'notes',''),actor) returning orders.id into id;
 else
 select * into o from private.orders where orders.id=id for update; if not found then raise exception using errcode='P0002',message='Order not found'; end if;
 perform private.expect_version(o.version,expected); if o.status<>'pending' then raise exception using errcode='40001',message='Only pending orders can be edited'; end if; before_data:=to_jsonb(o);
 update private.orders set discount=coalesce((p_payload->>'discount')::numeric,discount),platform_fee=coalesce((p_payload->>'platform_fee')::numeric,platform_fee),delivery_cost=coalesce((p_payload->>'delivery_cost')::numeric,delivery_cost),tax=coalesce((p_payload->>'tax')::numeric,tax),notes=coalesce(p_payload->>'notes',notes),version=version+1,updated_at=now() where orders.id=id;
 end if;
 if p_payload ? 'items' then perform private.set_order_items(id,p_payload->'items'); elsif p_operation='order_create' then raise exception using errcode='22023',message='Order items required'; end if;
 perform private.allocate_order(id); result:=private.order_json(id,mgr);
 elsif p_operation='order_transition' then
 select * into o from private.orders where orders.id=id for update; if not found then raise exception using errcode='P0002',message='Order not found'; end if;
 perform private.expect_version(o.version,expected); before_data:=to_jsonb(o); newstatus:=p_payload->>'status';
 if not ((o.status='pending' and newstatus='preparing') or (o.status='preparing' and newstatus='ready') or (o.status='ready' and newstatus='completed') or (o.status in ('pending','preparing','ready') and newstatus='cancelled')) then raise exception using errcode='40001',message='Invalid order transition'; end if;
 if newstatus='cancelled' and length(btrim(coalesce(p_payload->>'reason','')))=0 then raise exception using errcode='22023',message='Cancellation reason required'; end if;
 if newstatus='preparing' then
 -- Lock menu versions before recipes; menu changes take the same row lock.
 perform 1 from private.menu_items mi join private.order_items oi on oi.menu_item_id=mi.id where oi.order_id=id order by mi.id for share of mi;
 
 perform 1 from private.ingredients i where i.id in(select r.ingredient_id from (select mi.id menu_item_id,mi.stock_ingredient_id ingredient_id,1::numeric quantity from private.menu_items mi where mi.stock_ingredient_id is not null) r join private.order_items oi on oi.menu_item_id=r.menu_item_id where oi.order_id=id) order by i.id for update;
 for item in select r.ingredient_id,sum(r.quantity*oi.quantity) needed from (select mi.id menu_item_id,mi.stock_ingredient_id ingredient_id,1::numeric quantity from private.menu_items mi where mi.stock_ingredient_id is not null) r join private.order_items oi on oi.menu_item_id=r.menu_item_id where oi.order_id=id group by r.ingredient_id order by r.ingredient_id loop
 select * into ing from private.ingredients where ingredients.id=item.ingredient_id;
 if not ing.is_active or ing.stock_quantity<item.needed then raise exception using errcode='40001',message='Not enough bottles in stock'; end if;
 update private.ingredients set stock_quantity=stock_quantity-item.needed,version=version+1,updated_at=now() where ingredients.id=ing.id;
 insert into private.inventory_transactions(ingredient_id,order_id,kind,quantity,unit_cost,value,reason,created_by) values(ing.id,id,'consumption',-item.needed,ing.average_unit_cost,-item.needed*ing.average_unit_cost,'Order preparation',actor);
 end loop;
 insert into private.order_consumptions(order_id,order_item_id,ingredient_id,quantity,unit_cost,cost)
 select id,oi.id,r.ingredient_id,r.quantity*oi.quantity,i.average_unit_cost,r.quantity*oi.quantity*i.average_unit_cost from private.order_items oi join (select mi.id menu_item_id,mi.stock_ingredient_id ingredient_id,1::numeric quantity from private.menu_items mi where mi.stock_ingredient_id is not null) r on r.menu_item_id=oi.menu_item_id join private.ingredients i on i.id=r.ingredient_id where oi.order_id=id;
 update private.order_items oi set ingredient_cost_snapshot=coalesce((select sum(c.cost) from private.order_consumptions c where c.order_item_id=oi.id),0),costing_complete=(menu_row.stock_ingredient_id is not null and exists(select 1 from private.order_consumptions cc where cc.order_item_id=oi.id and cc.unit_cost>0)),packaging_cost_snapshot=menu_row.packaging_cost,recipe_version=menu_row.version from private.menu_items menu_row where oi.order_id=id and menu_row.id=oi.menu_item_id;
 end if;
 update private.orders set status=newstatus,version=version+1,updated_at=now(),prepared_at=case when newstatus='preparing' then now() else prepared_at end,completed_at=case when newstatus='completed' then now() else completed_at end,cancelled_at=case when newstatus='cancelled' then now() else cancelled_at end,cancellation_reason=case when newstatus='cancelled' then p_payload->>'reason' else cancellation_reason end where orders.id=id;
 result:=private.order_json(id,mgr);
 elsif p_operation='expense_create' then
 if (p_payload->>'incurred_on')::date>(now() at time zone 'Asia/Karachi')::date then raise exception using errcode='22023',message='Expense cannot be future dated'; end if;
 if lower(p_payload->>'category') in ('inventory','ingredients','purchase') then raise exception using errcode='22023',message='Ingredient purchases must use inventory purchases'; end if;
 insert into private.expenses(category,amount,incurred_on,description,created_by) values(p_payload->>'category',(p_payload->>'amount')::numeric,(p_payload->>'incurred_on')::date,coalesce(p_payload->>'description',''),actor) returning expenses.id into id;
 result:=private.read_core('expenses',jsonb_build_object('id',id));
 elsif p_operation='expense_void' then
 select * into ex from private.expenses where expenses.id=id for update; if not found then raise exception using errcode='P0002',message='Expense not found'; end if;
 perform private.expect_version(ex.version,expected); if ex.voided_at is not null then raise exception using errcode='40001',message='Expense already voided'; end if;
 if length(btrim(coalesce(p_payload->>'reason','')))=0 then raise exception using errcode='22023',message='Void reason required'; end if;
 before_data:=to_jsonb(ex); update private.expenses set voided_at=now(),void_reason=p_payload->>'reason',version=version+1 where expenses.id=id; result:=private.read_core('expenses',jsonb_build_object('id',id));
 elsif p_operation='user_update' then
 if coalesce(p_payload->>'role','staff')<>'staff' or not exists(select 1 from private.profiles where profiles.id=id and role='staff') then raise exception using errcode='42501',message='Only staff accounts can be managed in the portal';end if;
 perform pg_advisory_xact_lock(hashtextextended('smartdine:managers',0));
 select * into prof from private.profiles where profiles.id=id for update; if not found then raise exception using errcode='P0002',message='User not found'; end if;
 perform private.expect_version(prof.version,expected); before_data:=to_jsonb(prof);
 if prof.is_active and prof.role='manager' and (coalesce(p_payload->>'role',prof.role)<>'manager' or not coalesce((p_payload->>'is_active')::boolean,prof.is_active)) and (select count(*) from private.profiles where role='manager' and is_active)=1 then raise exception using errcode='40001',message='Cannot remove last active manager'; end if;
 update private.profiles set staff_type=coalesce(p_payload->>'staff_type',staff_type),full_name=coalesce(p_payload->>'full_name',full_name),role=coalesce(p_payload->>'role',role),is_active=coalesce((p_payload->>'is_active')::boolean,is_active),version=version+1,updated_at=now() where profiles.id=id; result:=private.read_core('users',jsonb_build_object('id',id));
 elsif p_operation='review_token_create' then
 id:=coalesce(id,(p_payload->>'order_id')::uuid);
 select * into o from private.orders where orders.id=id for update;
 if not found or o.status<>'completed' then raise exception using errcode='22023',message='Completed order required'; end if;
 if exists(select 1 from private.review_tokens where order_id=id) then raise exception using errcode='40001',message='Review token already issued; retry the original idempotency key'; end if;
 token:=encode(extensions.gen_random_bytes(32),'hex');
 insert into private.review_tokens(order_id,token_hash,expires_at) values(id,encode(extensions.digest(token,'sha256'),'hex'),now()+interval '7 days');
 result:=jsonb_build_object('order_id',id,'token',token,'expires_at',now()+interval '7 days');
 elsif p_operation='recommendation_generate' then
 perform private.require_actor(true);
 perform pg_advisory_xact_lock(hashtextextended('smartdine:recommendation-generation',0));
 before_data:=private.analytics(p_payload-'report'); result:='[]';
 for item in select value from jsonb_array_elements(before_data->'items') loop
 if item.value->>'matrix'='low_volume/high_margin' and not exists(select 1 from private.recommendations where target_id=(item.value->>'menu_item_id')::uuid and action_type='marketing' and status in ('proposed','approved')) then
 result:=result||jsonb_build_array(private.command_core('recommendation_create',jsonb_build_object(
 'action_type','marketing','target_id',item.value->>'menu_item_id','title','Consider a promotion for '||(item.value->>'name'),
 'description','Low recorded volume and above-threshold contribution margin. Test a limited promotion and measure the result.',
 'proposed_change',jsonb_build_object('instructions','Manager to choose a limited promotion; no discount or price change is applied automatically.'),
 'evidence',jsonb_build_array(jsonb_build_object('source','analytics','reference',(before_data->>'start_date')||'/'||(before_data->>'end_date'),
 'summary','Units: '||(item.value->>'quantity')||'; contribution PKR: '||(item.value->>'contribution_margin')))),actor));
 end if;
 end loop;
 for item in select * from private.ingredients where is_active and reorder_level>0 and stock_quantity<=reorder_level order by id loop
 if not exists(select 1 from private.recommendations where target_id=item.id and action_type='reorder' and status in ('proposed','approved')) then
 result:=result||jsonb_build_array(private.command_core('recommendation_create',jsonb_build_object(
 'action_type','reorder','target_id',item.id,'title','Review replenishment for '||item.name,
 'description','Current stock has reached or fallen below the configured reorder level.',
 'proposed_change',jsonb_build_object('instructions','Manager to review quantity and supplier. Record inventory purchase only after goods arrive.'),
 'evidence',jsonb_build_array(jsonb_build_object('source','inventory','reference',item.id::text,
 'summary','Stock: '||item.stock_quantity::text||' '||item.unit||'; reorder level: '||item.reorder_level::text))),actor));
 end if;
 end loop;
 return jsonb_build_object('generator','rules-v1','items',result,'total',jsonb_array_length(result),'period',jsonb_build_object('start_date',before_data->'start_date','end_date',before_data->'end_date'));
 elsif p_operation='recommendation_create' then
 if coalesce(jsonb_typeof(p_payload->'evidence'),'null') not in ('array','object') or p_payload->'evidence' in ('[]'::jsonb,'{}'::jsonb) then raise exception using errcode='22023',message='Evidence is required'; end if;
 if jsonb_typeof(p_payload->'proposed_change') is distinct from 'object' then raise exception using errcode='22023',message='Proposed change object required'; end if;
 if p_payload->>'action_type'='price_update' and (not ((p_payload->'proposed_change') ? 'selling_price') or ((p_payload->'proposed_change')-'selling_price')<>'{}'::jsonb) then raise exception using errcode='22023',message='Price recommendation may only change selling_price'; end if;
 if p_payload->>'action_type'='recipe_update' and (jsonb_typeof(p_payload->'proposed_change'->'ingredients') is distinct from 'array' or ((p_payload->'proposed_change')-'ingredients')<>'{}'::jsonb) then raise exception using errcode='22023',message='Recipe recommendation requires ingredients only'; end if;
 if p_payload->>'action_type'='menu_update' and (p_payload->'proposed_change'='{}'::jsonb or ((p_payload->'proposed_change')-array['name','category','is_active','packaging_cost'])<>'{}'::jsonb) then raise exception using errcode='22023',message='Invalid menu recommendation fields'; end if;
 if p_payload->>'action_type' in ('marketing','reorder') and length(btrim(coalesce(p_payload->'proposed_change'->>'instructions','')))=0 then raise exception using errcode='22023',message='Manual task instructions required'; end if;
 if p_payload->>'action_type' in ('price_update','recipe_update','menu_update') and (p_payload->>'target_id' is null or p_payload->>'expected_target_version' is null) then raise exception using errcode='22023',message='Target and expected version required'; end if;
 insert into private.recommendations(action_type,title,description,target_id,expected_target_version,proposed_change,evidence,created_by) values(p_payload->>'action_type',p_payload->>'title',coalesce(p_payload->>'description',''),(p_payload->>'target_id')::uuid,(p_payload->>'expected_target_version')::int,p_payload->'proposed_change',p_payload->'evidence',actor) returning recommendations.id into id;
 result:=private.read_core('recommendations',jsonb_build_object('id',id));
 elsif p_operation in ('recommendation_approve','recommendation_reject','recommendation_apply') then
 select * into rec from private.recommendations where recommendations.id=id for update; if not found then raise exception using errcode='P0002',message='Recommendation not found'; end if;
 perform private.expect_version(rec.version,expected); before_data:=to_jsonb(rec);
 if p_operation='recommendation_approve' then
 if rec.status<>'proposed' then raise exception using errcode='40001',message='Only proposed recommendations can be approved'; end if;
 update private.recommendations set status='approved',approved_by=actor,approved_at=now(),version=version+1 where recommendations.id=id;
 elsif p_operation='recommendation_reject' then
 if rec.status not in ('proposed','approved') then raise exception using errcode='40001',message='Recommendation cannot be rejected'; end if;
 update private.recommendations set status='rejected',version=version+1 where recommendations.id=id;
 else
 if rec.status<>'approved' then raise exception using errcode='40001',message='Approved recommendation required'; end if;
 if rec.action_type in ('marketing','reorder') then raise exception using errcode='22023',message='This recommendation is an approved manual task; stock receipt uses inventory purchase'; end if;
 if rec.action_type='recipe_update' then perform private.set_recipe(rec.target_id,rec.proposed_change->'ingredients',rec.expected_target_version,actor);
 else
 result:=private.command_core('menu_update',rec.proposed_change||jsonb_build_object('id',rec.target_id,'expected_version',rec.expected_target_version),actor);
 end if;
 update private.recommendations set status='applied',applied_at=now(),version=version+1 where recommendations.id=id;
 end if; result:=private.read_core('recommendations',jsonb_build_object('id',id));
 else return private.command_intelligence(p_operation,p_payload,actor); end if;
 perform private.audit(actor,p_operation,p_operation,id,before_data,case when p_operation='review_token_create' then result-'token' else result end);
 return private.json_decimals(result);
end $$;


ALTER FUNCTION private.command_core_before_menu_delete(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO sd_branch_executor;

--
-- Name: command_core_before_simple_stock(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_core_before_simple_stock(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare item private.menu_items; result jsonb;
begin
 if p_operation='menu_delete' then
  if private.require_actor(true)<>p_actor then raise exception using errcode='42501',message='Actor mismatch';end if;
  select * into item from private.menu_items where id=(p_payload->>'id')::uuid and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Dish not found';end if;
  perform private.expect_version(item.version,(p_payload->>'expected_version')::integer);
  if exists(select 1 from private.order_items oi join private.orders o on o.id=oi.order_id where oi.menu_item_id=item.id and o.status in ('pending','preparing','ready')) then
   raise exception using errcode='40001',message='Complete or cancel active orders containing this dish before deleting it';
  end if;
  update private.menu_items set is_active=false,deleted_at=now(),updated_at=now(),version=version+1 where id=item.id;
  result:=jsonb_build_object('id',item.id,'status','deleted');
  perform private.audit(p_actor,'menu_delete','menu_items',item.id,to_jsonb(item),result);
  return result;
 end if;
 if p_operation in ('menu_update','recipe_set') and exists(select 1 from private.menu_items where id=(p_payload->>'id')::uuid and deleted_at is not null) then
  raise exception using errcode='P0002',message='Dish has been deleted';
 end if;
 return private.command_core_before_menu_delete(p_operation,p_payload,p_actor);
end $$;


ALTER FUNCTION private.command_core_before_simple_stock(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: command_core_before_staff_immutability(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_core_before_staff_immutability(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
 f private.floors;
 t private.dining_tables;
 o private.orders;
 result jsonb;
 before_data jsonb;
 entity uuid;
 kind text;
 subtot numeric;
 calc_tax numeric;
 total numeric;
 received numeric;
 disc_amt numeric;
 disc_pct numeric;
 is_mgr boolean;
 prof private.profiles;
begin
 select * into prof from private.profiles where id=p_actor;
 is_mgr := (prof.role = 'manager');

 -- 1. Cashier payment with discount support
 if p_operation = 'order_pay' then
  if prof.role <> 'manager' and prof.staff_type <> 'cashier' then
   raise exception using errcode='42501',message='Cashier access required';
  end if;
  select * into o from private.orders where id=(p_payload->>'id')::uuid for update;
  if not found then raise exception using errcode='P0002',message='Bill not found'; end if;
  perform private.expect_version(o.version,(p_payload->>'expected_version')::integer);
  if o.status <> 'ready' then raise exception using errcode='40001',message='Only ready, unpaid orders can be paid'; end if;
  
  subtot := (select coalesce(sum(quantity*price_snapshot),0) from private.order_items where order_id=o.id);
  
  -- Check for cashier discount
  if p_payload ? 'discount_percent' and (p_payload->>'discount_percent')::numeric is not null then
   disc_pct := round((p_payload->>'discount_percent')::numeric, 2);
   if disc_pct < 0 or disc_pct > 100 then
    raise exception using errcode='22023',message='Discount percent must be between 0 and 100';
   end if;
   disc_amt := round(subtot * (disc_pct / 100.0), 2);
  elsif p_payload ? 'discount' and (p_payload->>'discount')::numeric is not null then
   disc_amt := round((p_payload->>'discount')::numeric, 2);
   if disc_amt < 0 or disc_amt > subtot then
    raise exception using errcode='22023',message='Discount cannot exceed subtotal';
   end if;
   disc_pct := case when subtot > 0 then round((disc_amt / subtot) * 100.0, 2) else 0 end;
  else
   disc_amt := coalesce(o.discount, 0);
   disc_pct := o.discount_percent;
  end if;

  update private.orders set
   discount = disc_amt,
   discount_percent = disc_pct,
   discount_reason = nullif(btrim(p_payload->>'discount_reason'), '')
  where id=o.id;

  total := subtot - disc_amt + o.tax;
  received := (p_payload->>'cash_received')::numeric;
  if received is null or received < total or received <> round(received, 2) then
   raise exception using errcode='22023',message='Cash received must cover the full bill';
  end if;

  update private.orders set
   paid_by = p_actor,
   cash_received = received,
   change_given = received - total
  where id=o.id;

  result := private.command_core_before_cashier('order_transition', jsonb_build_object('id', o.id, 'expected_version', o.version, 'status', 'completed'), p_actor);
  perform private.audit(p_actor, 'order_paid', 'orders', o.id, null, jsonb_build_object(
   'subtotal', subtot,
   'tax', o.tax,
   'tax_rate', o.tax_rate_snapshot,
   'discount', disc_amt,
   'discount_percent', disc_pct,
   'discount_reason', p_payload->>'discount_reason',
   'total', total,
   'cash_received', received,
   'change_given', received - total
  ));
  return result;
 end if;

 -- 2. Order creation & update with automatic table tax calculation
 if p_operation in ('order_create', 'order_update') and p_payload ? 'table_id' then
  perform private.require_actor(false);
  select * into t from private.dining_tables where id=(p_payload->>'table_id')::uuid for share;
  if not found then raise exception using errcode='P0002',message='Select an existing table'; end if;
  select * into f from private.floors where id=t.floor_id for share;

  -- Waiters cannot set discount or tax
  if not is_mgr then
   p_payload := p_payload - 'discount' - 'tax';
  end if;

  result := private.command_core_before_table_tax(p_operation, p_payload, p_actor);
  
  -- Calculate automated tax based on table tax_rate and order items
  subtot := (select coalesce(sum(quantity*price_snapshot),0) from private.order_items where order_id=(result->>'id')::uuid);
  calc_tax := round(subtot * (coalesce(t.tax_rate, 15.00) / 100.0), 2);

  update private.orders set
   table_id = t.id,
   floor_name_snapshot = f.name,
   table_name_snapshot = t.name,
   seats_snapshot = t.seats,
   tax_rate_snapshot = coalesce(t.tax_rate, 15.00),
   tax = calc_tax
  where id=(result->>'id')::uuid;

  return private.order_json((result->>'id')::uuid, is_mgr);
 end if;

 -- 3. Bulk floor tax rate set
 if p_operation = 'floor_set_tax' then
  if private.require_actor(true) <> p_actor then raise exception using errcode='42501',message='Manager required'; end if;
  select * into f from private.floors where id=(p_payload->>'floor_id')::uuid;
  if not found then raise exception using errcode='P0002',message='Floor not found'; end if;
  if (p_payload->>'tax_rate')::numeric is null or (p_payload->>'tax_rate')::numeric < 0 or (p_payload->>'tax_rate')::numeric > 100 then
   raise exception using errcode='22023',message='Tax rate must be between 0 and 100 percent';
  end if;
  update private.dining_tables set
   tax_rate = round((p_payload->>'tax_rate')::numeric, 2),
   version = version + 1
  where floor_id = f.id;
  result := jsonb_build_object('floor_id', f.id, 'tax_rate', round((p_payload->>'tax_rate')::numeric, 2), 'status', 'updated');
  perform private.audit(p_actor, 'floor_set_tax', 'floors', f.id, null, result);
  return result;
 end if;

 -- 4. Table creation & update with tax_rate
 if p_operation in ('table_create', 'table_update') then
  if private.require_actor(true) <> p_actor then raise exception using errcode='42501',message='Manager required'; end if;
  kind := 'dining_tables';
  if p_operation = 'table_update' then
   select * into t from private.dining_tables where id=(p_payload->>'id')::uuid for update;
   if not found then raise exception using errcode='P0002',message='Table not found'; end if;
   perform private.expect_version(t.version,(p_payload->>'expected_version')::integer);
   before_data := to_jsonb(t);
  end if;
  select * into f from private.floors where id=(p_payload->>'floor_id')::uuid for key share;
  if not found then raise exception using errcode='P0002',message='Floor not found'; end if;

  if p_operation = 'table_create' then
   insert into private.dining_tables(floor_id, name, seats, tax_rate)
   values(f.id, btrim(p_payload->>'name'), (p_payload->>'seats')::integer, coalesce((p_payload->>'tax_rate')::numeric, 15.00))
   returning * into t;
  else
   update private.dining_tables set
    floor_id = f.id,
    name = btrim(p_payload->>'name'),
    seats = (p_payload->>'seats')::integer,
    tax_rate = coalesce((p_payload->>'tax_rate')::numeric, t.tax_rate, 15.00),
    version = version + 1
   where id = t.id
   returning * into t;
  end if;
  entity := t.id;
  result := to_jsonb(t);
  perform private.audit(p_actor, p_operation, kind, entity, before_data, result);
  return result;
 end if;

 return private.command_core_before_table_tax(p_operation, p_payload, p_actor);
end;
$$;


ALTER FUNCTION private.command_core_before_staff_immutability(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: command_core_before_table_tax(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_core_before_table_tax(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare f private.floors; t private.dining_tables; result jsonb; before_data jsonb; entity uuid; kind text;
begin
 if p_operation='order_create' and not (p_payload ? 'table_id') and exists(select 1 from private.dining_tables) then
  raise exception using errcode='22023',message='Select a floor and table for this order';
 end if;
 if p_operation in ('order_create','order_update') and p_payload ? 'table_id' then
  perform private.require_actor(false);
  select * into t from private.dining_tables where id=(p_payload->>'table_id')::uuid for share;
  if not found then raise exception using errcode='P0002',message='Select an existing table';end if;
  select * into f from private.floors where id=t.floor_id for share;
  result:=private.command_core_before_floor_tables(p_operation,p_payload,p_actor);
  update private.orders set table_id=t.id,floor_name_snapshot=f.name,table_name_snapshot=t.name,seats_snapshot=t.seats where id=(result->>'id')::uuid;
  return private.order_json((result->>'id')::uuid,(select role='manager' from private.profiles where id=p_actor));
 end if;
 if p_operation not in ('floor_create','floor_update','floor_delete','table_create','table_update','table_delete') then
  return private.command_core_before_floor_tables(p_operation,p_payload,p_actor);
 end if;
 if private.require_actor(true)<>p_actor then raise exception using errcode='42501',message='Manager required';end if;
 if p_operation like 'floor_%' then
  kind:='floors';
  if p_operation='floor_create' then
   insert into private.floors(name) values(btrim(p_payload->>'name')) returning * into f;
  else
   select * into f from private.floors where id=(p_payload->>'id')::uuid for update;
   if not found then raise exception using errcode='P0002',message='Floor not found';end if;
   perform private.expect_version(f.version,(p_payload->>'expected_version')::integer);before_data:=to_jsonb(f);
   if p_operation='floor_delete' then
    if exists(select 1 from private.dining_tables where floor_id=f.id) then raise exception using errcode='22023',message='Move or delete the tables on this floor first';end if;
    delete from private.floors where id=f.id;
   else
    update private.floors set name=btrim(p_payload->>'name'),version=version+1 where id=f.id returning * into f;
   end if;
  end if;
  entity:=f.id;result:=to_jsonb(f);
 else
  kind:='dining_tables';
  if p_operation<>'table_create' then
   select * into t from private.dining_tables where id=(p_payload->>'id')::uuid for update;
   if not found then raise exception using errcode='P0002',message='Table not found';end if;
   perform private.expect_version(t.version,(p_payload->>'expected_version')::integer);before_data:=to_jsonb(t);
  end if;
  if p_operation='table_delete' then
   if exists(select 1 from private.orders where table_id=t.id and status in ('pending','preparing','ready')) then raise exception using errcode='22023',message='Complete or cancel this table''s active orders before deleting it';end if;
   delete from private.dining_tables where id=t.id;
  else
   select * into f from private.floors where id=(p_payload->>'floor_id')::uuid for key share;
   if not found then raise exception using errcode='P0002',message='Floor not found';end if;
   if p_operation='table_create' then
    insert into private.dining_tables(floor_id,name,seats) values(f.id,btrim(p_payload->>'name'),(p_payload->>'seats')::integer) returning * into t;
   else
    update private.dining_tables set floor_id=f.id,name=btrim(p_payload->>'name'),seats=(p_payload->>'seats')::integer,version=version+1 where id=t.id returning * into t;
   end if;
  end if;
  entity:=t.id;result:=to_jsonb(t);
 end if;
 perform private.audit(p_actor,p_operation,kind,entity,before_data,result);
 return result;
end $$;


ALTER FUNCTION private.command_core_before_table_tax(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: command_intelligence(text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.command_intelligence(p_operation text, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_actor uuid;v_today date:=(now() at time zone 'Asia/Karachi')::date;v_day date;
 v_id uuid;v_item uuid;v_jobs jsonb:='[]';v_row jsonb;v_existing private.historical_sales%rowtype;
 v_count integer;v_status text;v_job private.processing_jobs%rowtype;
begin
 v_actor:=private.require_actor(true);
 if v_actor is distinct from p_actor then raise exception using errcode='42501',message='Actor mismatch';end if;
 case p_operation
 when 'forecast_enqueue' then
  if jsonb_typeof(p_payload->'menu_item_ids') is distinct from 'array' or jsonb_array_length(p_payload->'menu_item_ids') not between 1 and 100 then
   raise exception using errcode='22023',message='Choose 1 to 100 menu items';end if;
  for v_item in select distinct value::uuid from jsonb_array_elements_text(p_payload->'menu_item_ids') loop
   if not exists(select 1 from private.menu_items where id=v_item) then raise exception using errcode='P0002',message='Menu item not found';end if;
   v_id:=private.enqueue_job('forecast',jsonb_build_object('menu_item_id',v_item,'as_of',v_today),'forecast:'||v_item||':'||v_today,v_actor);
   v_jobs:=v_jobs||jsonb_build_array(jsonb_build_object('job_id',v_id,'menu_item_id',v_item));
  end loop;
  return jsonb_build_object('jobs',v_jobs,'status','accepted');
 when 'job_retry' then
  select * into v_job from private.processing_jobs where id=(p_payload->>'job_id')::uuid for update;
  if not found then raise exception using errcode='P0002',message='Job not found';end if;
  if v_job.status<>'failed' then raise exception using errcode='40001',message='Only failed jobs can be retried';end if;
  update private.processing_jobs set status='queued',attempts=0,owner_token=null,lease_expires_at=null,available_at=now(),last_error_code=null where id=v_job.id;
  if v_job.kind='review_analysis' then update private.reviews set analysis_status='pending' where id=(v_job.payload->>'review_id')::uuid;end if;
  perform private.audit(v_actor,'job_retry','processing_jobs',v_job.id,to_jsonb(v_job),jsonb_build_object('status','queued'));
  return jsonb_build_object('job_id',v_job.id,'status','queued');
 when 'day_close' then
  v_day:=(p_payload->>'day')::date;v_status:=p_payload->>'status';
  if v_day is null or v_day>=v_today or v_status not in ('complete','closed') or length(btrim(coalesce(p_payload->>'note',''))) not between 1 and 500 then
   raise exception using errcode='22023',message='Close only past days with an explicit status and note';end if;
  perform pg_advisory_xact_lock(hashtextextended('coverage:'||v_day,0));
  if exists(select 1 from private.daily_coverage where day=v_day) then raise exception using errcode='40001',message='Day is already covered';end if;
  if v_status='closed' and exists(select 1 from private.orders where status='completed' and (completed_at at time zone 'Asia/Karachi')::date=v_day) then
   raise exception using errcode='22023',message='A day with completed sales cannot be marked closed';end if;
  insert into private.daily_coverage(day,source,status,note,closed_by) values(v_day,'live',v_status,p_payload->>'note',v_actor);
  perform private.audit(v_actor,'day_close','daily_coverage',null,null,jsonb_build_object('day',v_day,'status',v_status));
  return jsonb_build_object('day',v_day,'status',v_status,'source','live');
 when 'history_import' then
  if jsonb_typeof(p_payload->'rows') is distinct from 'array' or jsonb_array_length(p_payload->'rows') not between 1 and 10000
   or length(btrim(coalesce(p_payload->>'source_name',''))) not between 1 and 120 then
   raise exception using errcode='22023',message='Import needs a source and 1 to 10000 explicit item/day rows';end if;
  insert into private.history_imports(source_name,actor_id,row_count) values(p_payload->>'source_name',v_actor,jsonb_array_length(p_payload->'rows')) returning id into v_id;
  -- All imports acquire day locks in chronological order before checking overlap.
  for v_day in select distinct (value->>'day')::date from jsonb_array_elements(p_payload->'rows') order by 1 loop
   if v_day is null or v_day>=v_today then raise exception using errcode='22023',message='Historical observations must precede today';end if;
   perform pg_advisory_xact_lock(hashtextextended('coverage:'||v_day,0));
   if exists(select 1 from private.daily_coverage where day=v_day and source='live') or
    exists(select 1 from private.orders where status='completed' and (completed_at at time zone 'Asia/Karachi')::date=v_day) then
    raise exception using errcode='40001',message='Imported observations cannot overlap live sales or live coverage';end if;
  end loop;
  for v_row in select value from jsonb_array_elements(p_payload->'rows') loop
   v_day:=(v_row->>'day')::date;v_item:=(v_row->>'menu_item_id')::uuid;v_count:=(v_row->>'quantity')::integer;v_status:=v_row->>'day_status';
   if v_item is null or v_count is null or v_count not between 0 and 1000000 or v_status is null or v_status not in ('complete','closed') or (v_status='closed' and v_count<>0) then
    raise exception using errcode='22023',message='Invalid historical observation';end if;
   select * into v_existing from private.historical_sales where day=v_day and menu_item_id=v_item;
   if found and (v_existing.quantity<>v_count or v_existing.day_status<>v_status) then
    raise exception using errcode='40001',message='Conflicting duplicate historical observation';end if;
   if exists(select 1 from private.daily_coverage where day=v_day and status<>v_status) then
    raise exception using errcode='40001',message='Day status conflicts with existing coverage';end if;
   insert into private.historical_sales(day,menu_item_id,quantity,day_status,import_id) values(v_day,v_item,v_count,v_status,v_id) on conflict(day,menu_item_id) do nothing;
   insert into private.daily_coverage(day,source,status,note,closed_by) values(v_day,'historical',v_status,p_payload->>'source_name',v_actor) on conflict(branch_id,day) do nothing;
  end loop;
  perform private.audit(v_actor,'history_import','history_imports',v_id,null,jsonb_build_object('row_count',jsonb_array_length(p_payload->'rows')));
  return jsonb_build_object('import_id',v_id,'observations',jsonb_array_length(p_payload->'rows'));
 else raise exception using errcode='22023',message='Unknown command';
 end case;
end $$;


ALTER FUNCTION private.command_intelligence(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: current_branch(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_branch() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select branch_id from private.profiles where id=auth.uid()),nullif(current_setting('app.branch_id',true),'')::uuid)
$$;


ALTER FUNCTION private.current_branch() OWNER TO postgres;

--
-- Name: enqueue_job(text, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_job(p_kind text, p_payload jsonb, p_dedup_key text, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
 if p_kind not in ('review_analysis','forecast') or length(p_dedup_key)>200 then
  raise exception using errcode='22023',message='Invalid job';
 end if;
 insert into private.processing_jobs(kind,payload,deduplication_key,actor_id)
 values(p_kind,p_payload,p_dedup_key,p_actor) on conflict(deduplication_key) do nothing returning id into v_id;
 if v_id is null then select id into v_id from private.processing_jobs where deduplication_key=p_dedup_key; end if;
 return v_id;
end $$;


ALTER FUNCTION private.enqueue_job(p_kind text, p_payload jsonb, p_dedup_key text, p_actor uuid) OWNER TO postgres;

--
-- Name: execute_command(text, jsonb, text); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.execute_command(p_operation text, p_payload jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor uuid:=private.require_actor(false); prof private.profiles;
begin
 select * into prof from private.profiles where id=actor;
 if not found or not prof.is_active then raise exception using errcode='42501',message='Active profile required';end if;

 -- Kitchen and cashier staff cannot create or edit dining table orders (floor staff only)
 if prof.role='staff' and prof.staff_type in ('kitchen','cashier') and p_operation in ('order_create','order_update') then
   raise exception using errcode='42501',message='Kitchen and cashier staff cannot create or edit table orders';
 end if;

 -- Only kitchen or manager can mark an order preparing or ready for pickup
 if p_operation='order_transition' and p_payload->>'status' in ('preparing','ready') and prof.role<>'manager' and prof.staff_type<>'kitchen' then
   raise exception using errcode='42501',message='Kitchen or manager access is required to prepare or plate orders';
 end if;

 return private.execute_command_before_station_boundaries(p_operation,p_payload,p_idempotency_key);
end $$;


ALTER FUNCTION private.execute_command(p_operation text, p_payload jsonb, p_idempotency_key text) OWNER TO sd_branch_executor;

--
-- Name: execute_command_before_cashier(text, jsonb, text); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.execute_command_before_cashier(p_operation text, p_payload jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor uuid:=private.require_actor(false); h text; prior private.idempotency_records; result jsonb; mgr boolean;
begin
 select role='manager' into mgr from private.profiles where id=actor;
 if p_operation<>all(array['order_pay','inventory_record','order_create','order_update','order_transition','expense_create','review_token_create']) then perform private.require_actor(true); end if;
 if p_operation is null or jsonb_typeof(p_payload) is distinct from 'object' or length(coalesce(p_idempotency_key,'')) not between 1 and 200 then raise exception using errcode='22023',message='Operation, object payload and Idempotency-Key required'; end if;
 perform private.validate_payload(p_payload);
 case p_operation
 when 'menu_create' then perform private.required_fields(p_payload,array['name','selling_price']);
 when 'ingredient_create' then perform private.required_fields(p_payload,array['name','unit']);
 when 'recipe_set' then perform private.required_fields(p_payload,array['id','expected_version','ingredients']);
 when 'inventory_record' then perform private.required_fields(p_payload,array['ingredient_id','kind','quantity','reason']);
 when 'order_create' then perform private.required_fields(p_payload,array['items']);
 when 'order_transition' then perform private.required_fields(p_payload,array['id','expected_version','status']);
 when 'expense_create' then perform private.required_fields(p_payload,array['category','amount','incurred_on']);
 when 'expense_void' then perform private.required_fields(p_payload,array['id','expected_version','reason']);
 when 'recommendation_create' then perform private.required_fields(p_payload,array['action_type','title','proposed_change','evidence']);
 when 'menu_update','ingredient_update','order_update','user_update','recommendation_approve','recommendation_apply','recommendation_reject' then perform private.required_fields(p_payload,array['id','expected_version']);
 else null;
 end case;
 h:=encode(extensions.digest(p_payload::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_operation||':'||p_idempotency_key,0));
 select * into prior from private.idempotency_records where actor_id=actor and operation=p_operation and key=p_idempotency_key;
 if found then if prior.request_hash<>h then raise exception using errcode='23505',message='Idempotency key was already used with a different payload'; end if; return case when mgr then prior.result else private.staff_json(prior.result) end; end if;
 result:=private.command_core(p_operation,p_payload,actor);
 insert into private.idempotency_records(actor_id,operation,key,request_hash,result) values(actor,p_operation,p_idempotency_key,h,result);
 return result;
end $$;


ALTER FUNCTION private.execute_command_before_cashier(p_operation text, p_payload jsonb, p_idempotency_key text) OWNER TO sd_branch_executor;

--
-- Name: execute_command_before_station_boundaries(text, jsonb, text); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.execute_command_before_station_boundaries(p_operation text, p_payload jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor uuid := private.require_actor(false);
  prof private.profiles;
begin
  select * into prof from private.profiles where id = actor;
  if prof.role = 'staff'
     and prof.staff_type = 'cashier'
     and p_operation not in ('order_pay', 'review_token_create') then
    raise exception using errcode = '42501', message = 'Cashier access is limited to bills, payments and receipt review links';
  end if;
  if p_operation = 'order_pay' and prof.role <> 'manager' and prof.staff_type <> 'cashier' then
    raise exception using errcode = '42501', message = 'Cashier access required';
  end if;
  if p_operation = 'order_transition' and p_payload->>'status' = 'completed' then
    raise exception using errcode = '42501', message = 'Use cashier payment to mark an order paid';
  end if;
  return private.execute_command_before_cashier(p_operation, p_payload, p_idempotency_key);
end;
$$;


ALTER FUNCTION private.execute_command_before_station_boundaries(p_operation text, p_payload jsonb, p_idempotency_key text) OWNER TO sd_branch_executor;

--
-- Name: expect_version(integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.expect_version(p_actual integer, p_expected integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if p_expected is null then raise exception using errcode='22023',message='expected_version is required'; end if;
 if p_actual<>p_expected then raise exception using errcode='40001',message='Record changed; refresh before retrying'; end if;
end $$;


ALTER FUNCTION private.expect_version(p_actual integer, p_expected integer) OWNER TO postgres;

--
-- Name: json_decimals(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.json_decimals(p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare k text; v jsonb; r jsonb; begin
 if jsonb_typeof(p_value)='array' then
 select coalesce(jsonb_agg(private.json_decimals(value)),'[]'::jsonb) into r from jsonb_array_elements(p_value); return r;
 elsif jsonb_typeof(p_value)='object' then
 r:='{}'; for k,v in select * from jsonb_each(p_value) loop
 if jsonb_typeof(v)='number' and ((k ~ '(price|cost|amount|revenue|profit|margin|discount|fee|tax|value|stock|level|loss|expenses|threshold)' and k not in ('stock_count')) or k in ('subtotal','cash_received','change_given') or (k='total' and not (p_value ? 'limit')) or (k='quantity' and (p_value ? 'kind' or p_value ? 'unit_cost'))) then r:=r||jsonb_build_object(k,v#>>'{}');
 else r:=r||jsonb_build_object(k,private.json_decimals(v)); end if; end loop; return r;
 end if; return p_value; end $$;


ALTER FUNCTION private.json_decimals(p_value jsonb) OWNER TO postgres;

--
-- Name: order_json(uuid, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.order_json(p_id uuid, p_manager boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select (to_jsonb(o) - case when p_manager then '{}'::text[] else array['platform_fee','delivery_cost'] end) || jsonb_build_object(
 'subtotal',(select coalesce(sum(quantity*price_snapshot),0) from private.order_items where order_id=o.id),
 'tax_rate',coalesce(o.tax_rate_snapshot, 15.00),
 'discount_percent',o.discount_percent,
 'discount_reason',o.discount_reason,
 'total',(select coalesce(sum(quantity*price_snapshot),0) from private.order_items where order_id=o.id)-o.discount+o.tax,'items',
 coalesce((select jsonb_agg(to_jsonb(i)-case when p_manager then '{}'::text[] else array['ingredient_cost_snapshot','packaging_cost_snapshot','fee_allocated','recipe_version'] end order by i.id) from private.order_items i where i.order_id=o.id),'[]'::jsonb))
 from private.orders o where o.id=p_id
$$;


ALTER FUNCTION private.order_json(p_id uuid, p_manager boolean) OWNER TO postgres;

--
-- Name: read_core(text, jsonb); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.read_core(p_resource text, p_params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; total integer; prof private.profiles; q text:=lower(coalesce(p_params->>'q','')); lim integer:=coalesce((p_params->>'limit')::integer,50); offst integer:=coalesce((p_params->>'offset')::integer,0);
begin
 if p_resource='receipt' then
  result:=private.read_core_before_floor_tables(p_resource,p_params);
  return result||jsonb_build_object('receipt_number',result->>'order_number');
 end if;
 if p_resource='orders' and q<>'' then
  select * into prof from private.profiles where id=private.require_actor(false);
  if lim not between 1 and 100 or offst<0 then raise exception using errcode='22023',message='Invalid pagination';end if;
  select count(*) into total from private.orders o where position(q in lower(concat_ws(' ',o.id,o.order_number,o.notes,o.floor_name_snapshot,o.table_name_snapshot,o.created_by_name,o.created_by_email,o.prepared_by_name,o.prepared_by_email,o.paid_by_name,o.paid_by_email)))>0 and (p_params->>'status' is null or o.status=p_params->>'status');
  select coalesce(jsonb_agg(private.order_json(x.id,prof.role='manager') order by x.created_at desc,x.id),'[]') into result from (
   select o.id,o.created_at from private.orders o where position(q in lower(concat_ws(' ',o.id,o.order_number,o.notes,o.floor_name_snapshot,o.table_name_snapshot,o.created_by_name,o.created_by_email,o.prepared_by_name,o.prepared_by_email,o.paid_by_name,o.paid_by_email)))>0 and (p_params->>'status' is null or o.status=p_params->>'status') order by o.created_at desc,o.id limit lim offset offst
  ) x;
  return private.json_decimals(jsonb_build_object('items',result,'total',total,'limit',lim,'offset',offst));
 end if;
 if p_resource not in ('floors','tables') then return private.read_core_before_floor_tables(p_resource,p_params);end if;
 select * into prof from private.profiles where id=private.require_actor(false);
 if prof.role<>'manager' and prof.staff_type<>'waiter' then raise exception using errcode='42501',message='Floor access requires manager or waiter';end if;
 if lim not between 1 and 100 or offst<0 then raise exception using errcode='22023',message='Invalid pagination';end if;
 if p_resource='floors' then
  select count(*) into total from private.floors;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into result from (
   select f.*,(select count(*) from private.dining_tables t where t.floor_id=f.id) as table_count,
    (select coalesce(sum(seats),0) from private.dining_tables t where t.floor_id=f.id) as total_seats
   from private.floors f order by f.name,f.id limit lim offset offst
  ) x;
 else
  select count(*) into total from private.dining_tables where floor_id=(p_params->>'floor_id')::uuid;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into result from (
   select * from private.dining_tables where floor_id=(p_params->>'floor_id')::uuid order by name,id limit lim offset offst
  ) x;
 end if;
 return jsonb_build_object('items',result,'total',total,'limit',lim,'offset',offst);
end $$;


ALTER FUNCTION private.read_core(p_resource text, p_params jsonb) OWNER TO sd_branch_executor;

--
-- Name: read_core_before_cashier(text, jsonb); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.read_core_before_cashier(p_resource text, p_params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; total integer; lim integer:=coalesce((p_params->>'limit')::integer,50); offst integer:=coalesce((p_params->>'offset')::integer,0);
begin
 if p_resource='stock_products' then
  perform private.require_actor(true);
  if lim not between 1 and 200 or offst<0 then raise exception using errcode='22023',message='Invalid pagination';end if;
  select count(*) into total from private.ingredients i join private.menu_items m on m.stock_ingredient_id=i.id where m.deleted_at is null;
  select coalesce(jsonb_agg(to_jsonb(t)),'[]') into result from (
   select i.id,m.id menu_item_id,m.name,i.stock_quantity,i.reorder_level,m.selling_price,
    coalesce((select sum(quantity) from private.inventory_transactions where ingredient_id=i.id and kind='purchase'),0) received,
    coalesce((select -sum(quantity) from private.inventory_transactions where ingredient_id=i.id and kind='consumption'),0) used,
    coalesce((select -sum(quantity) from private.inventory_transactions where ingredient_id=i.id and kind='wastage'),0) removed
   from private.ingredients i join private.menu_items m on m.stock_ingredient_id=i.id where m.deleted_at is null order by m.name limit lim offset offst
  ) t;
  return jsonb_build_object('items',result,'total',total,'limit',lim,'offset',offst);
 end if;
 return private.read_core_before_simple_stock(p_resource,p_params);
end $$;


ALTER FUNCTION private.read_core_before_cashier(p_resource text, p_params jsonb) OWNER TO sd_branch_executor;

--
-- Name: read_core_before_floor_tables(text, jsonb); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.read_core_before_floor_tables(p_resource text, p_params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor uuid:=private.require_actor(false); prof private.profiles; o private.orders; result jsonb; total integer;
 lim integer:=coalesce((p_params->>'limit')::integer,50); offst integer:=coalesce((p_params->>'offset')::integer,0); state text:=coalesce(p_params->>'payment_status','unpaid');
begin
 select * into prof from private.profiles where id=actor;
 if prof.role='staff' and prof.staff_type='cashier' and p_resource not in ('me','profile','orders','bills','receipt') then raise exception using errcode='42501',message='Cashier access is limited to bills';end if;
 if p_resource in ('me','profile') then return private.read_core_before_cashier(p_resource,p_params)||jsonb_build_object('cashier_billing_enabled',true);end if;
 if p_resource in ('bills','receipt') then
  if prof.role<>'manager' and prof.staff_type<>'cashier' then raise exception using errcode='42501',message='Cashier access required';end if;
  if p_resource='receipt' then
   select * into o from private.orders where id=(p_params->>'id')::uuid;
   if not found then raise exception using errcode='P0002',message='Bill not found';end if;
   result:=private.order_json(o.id,false)||jsonb_build_object('receipt_number','SD-'||o.id::text,'branch_name',(select name from private.branches where id=o.branch_id),'payment_status',case when o.status='completed' then 'paid' when o.status='cancelled' then 'cancelled' else 'unpaid' end);
   return private.json_decimals(result);
  end if;
  if lim not between 1 and 200 or offst<0 or state not in ('unpaid','paid','all') then raise exception using errcode='22023',message='Invalid bill filter';end if;
  select count(*) into total from private.orders where (state='all' or (state='paid' and status='completed') or (state='unpaid' and status in ('pending','preparing','ready')));
  select coalesce(jsonb_agg(private.order_json(t.id,false) order by t.created_at desc),'[]') into result from (
   select id,created_at from private.orders where (state='all' or (state='paid' and status='completed') or (state='unpaid' and status in ('pending','preparing','ready'))) order by created_at desc,id limit lim offset offst
  ) t;
  return private.json_decimals(jsonb_build_object('items',result,'total',total,'limit',lim,'offset',offst));
 end if;
 return private.read_core_before_cashier(p_resource,p_params);
end $$;


ALTER FUNCTION private.read_core_before_floor_tables(p_resource text, p_params jsonb) OWNER TO sd_branch_executor;

--
-- Name: read_core_before_simple_stock(text, jsonb); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.read_core_before_simple_stock(p_resource text, p_params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_variable
declare actor uuid:=private.require_actor(false); mgr boolean; id uuid:=(p_params->>'id')::uuid; lim integer:=coalesce((p_params->>'limit')::int,50); offst integer:=coalesce((p_params->>'offset')::int,0); allrows jsonb; result jsonb;
begin
 select role='manager' into mgr from private.profiles where profiles.id=actor;
 if lim not between 1 and 200 or offst<0 then raise exception using errcode='22023',message='Invalid pagination'; end if;
 if p_resource in ('me','profile') then return (select to_jsonb(p) from private.profiles p where p.id=actor); end if;
 if p_resource in ('users','recipes','analytics','reviews','recommendations','audit') then perform private.require_actor(true); end if;
 if p_resource='analytics' then return private.json_decimals(private.analytics(p_params));
 elsif p_resource='users' then select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc),'[]') into allrows from private.profiles t where t.role='staff' and (id is null or t.id=id);
 elsif p_resource='menu' then select coalesce(jsonb_agg(to_jsonb(t)-case when mgr then '{}'::text[] else array['packaging_cost'] end order by t.name),'[]') into allrows from private.menu_items t where (id is null or t.id=id) and t.deleted_at is null and (mgr or t.is_active);
 elsif p_resource='recipes' then select jsonb_build_object('id',m.id,'version',m.version,'ingredients',coalesce((select jsonb_agg(jsonb_build_object('ingredient_id',r.ingredient_id,'quantity',r.quantity::text,'name',i.name,'unit',i.unit) order by i.name) from private.recipes r join private.ingredients i on i.id=r.ingredient_id where r.menu_item_id=m.id),'[]')) into result from private.menu_items m where m.deleted_at is null and m.id=coalesce(id,(p_params->>'menu_item_id')::uuid); if result is null then raise exception using errcode='P0002',message='Recipe item not found'; end if; return result;
 elsif p_resource='orders' then select coalesce(jsonb_agg(private.order_json(t.id,mgr) order by t.created_at desc),'[]') into allrows from private.orders t where (id is null or t.id=id) and (p_params->>'status' is null or t.status=p_params->>'status');
 elsif p_resource='inventory' then select coalesce(jsonb_agg(to_jsonb(t)-case when mgr then '{}'::text[] else array['average_unit_cost'] end order by t.name),'[]') into allrows from private.ingredients t where id is null or t.id=id;
 elsif p_resource='inventory_transactions' then select coalesce(jsonb_agg(to_jsonb(t)-case when mgr then '{}'::text[] else array['unit_cost','value'] end order by t.created_at desc),'[]') into allrows from private.inventory_transactions t where (id is null or t.id=id) and (p_params->>'ingredient_id' is null or t.ingredient_id=(p_params->>'ingredient_id')::uuid);
 elsif p_resource='expenses' then select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc),'[]') into allrows from private.expenses t where (id is null or t.id=id) and (mgr or t.created_by=actor) and (p_params->>'start_date' is null or t.incurred_on>=(p_params->>'start_date')::date) and (p_params->>'end_date' is null or t.incurred_on<=(p_params->>'end_date')::date);
 elsif p_resource='reviews' then select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc),'[]') into allrows from private.reviews t where (id is null or t.id=id) and (p_params->>'menu_item_id' is null or t.menu_item_id=(p_params->>'menu_item_id')::uuid) and (p_params->>'start_date' is null or (t.created_at at time zone 'Asia/Karachi')::date>=(p_params->>'start_date')::date) and (p_params->>'end_date' is null or (t.created_at at time zone 'Asia/Karachi')::date<=(p_params->>'end_date')::date);
 elsif p_resource='recommendations' then select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc),'[]') into allrows from private.recommendations t where (id is null or t.id=id) and (p_params->>'status' is null or t.status=p_params->>'status');
 elsif p_resource='audit' then
 if p_params ? 'event_id' then
 select to_jsonb(t) into result from private.audit_logs t where t.id=(p_params->>'event_id')::bigint;
 if result is null then raise exception using errcode='P0002',message='Audit event not found'; end if;
 return private.json_decimals(result);
 end if;
 select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc),'[]') into allrows from private.audit_logs t;
 else return private.json_decimals(private.read_intelligence(p_resource,p_params)); end if;
 if id is not null then if jsonb_array_length(allrows)=0 then raise exception using errcode='P0002',message='Record not found'; end if; return private.json_decimals(allrows->0); end if;
 select coalesce(jsonb_agg(value),'[]') into result from (select value from jsonb_array_elements(allrows) with ordinality x(value,n) order by n limit lim offset offst) q;
 return private.json_decimals(jsonb_build_object('items',result,'total',jsonb_array_length(allrows),'limit',lim,'offset',offst));
end $$;


ALTER FUNCTION private.read_core_before_simple_stock(p_resource text, p_params jsonb) OWNER TO sd_branch_executor;

--
-- Name: read_intelligence(text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.read_intelligence(p_resource text, p_params jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_limit integer:=coalesce((p_params->>'limit')::integer,50);v_offset integer:=coalesce((p_params->>'offset')::integer,0);
 v_items jsonb;v_total bigint;v_item uuid:=nullif(p_params->>'menu_item_id','')::uuid;
begin
 perform private.require_actor(true);
 if v_limit not between 1 and 100 or v_offset<0 then raise exception using errcode='22023',message='Invalid pagination';end if;
 case p_resource
 when 'forecasts' then
  select count(*) into v_total from private.forecast_runs where v_item is null or menu_item_id=v_item;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into v_items from
   (select * from private.forecast_runs where v_item is null or menu_item_id=v_item order by created_at desc,id limit v_limit offset v_offset) q;
 when 'jobs' then
  select count(*) into v_total from private.processing_jobs;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into v_items from
   (select id,kind,payload,status,attempts,max_attempts,last_error_code,available_at,created_at,completed_at
    from private.processing_jobs order by created_at desc,id limit v_limit offset v_offset) q;
 when 'review_analyses' then
  select count(*) into v_total from private.review_analyses where p_params->>'review_id' is null or review_id=(p_params->>'review_id')::uuid;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into v_items from
   (select * from private.review_analyses where p_params->>'review_id' is null or review_id=(p_params->>'review_id')::uuid
    order by created_at desc,review_id limit v_limit offset v_offset) q;
 when 'assistant_runs' then
  select count(*) into v_total from private.assistant_runs;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into v_items from
   (select * from private.assistant_runs order by created_at desc,id limit v_limit offset v_offset) q;
 else raise exception using errcode='22023',message='Unknown read resource';
 end case;
 return jsonb_build_object('items',v_items,'total',v_total,'limit',v_limit,'offset',v_offset);
end $$;


ALTER FUNCTION private.read_intelligence(p_resource text, p_params jsonb) OWNER TO postgres;

--
-- Name: require_actor(boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.require_actor(p_manager boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_actor uuid := auth.uid(); v_profile private.profiles;
 v_session text:=nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'session_id';
begin
 select * into v_profile from private.profiles where id=v_actor;
 if v_actor is null or not found or not v_profile.is_active or (p_manager and v_profile.role<>'manager') then
 raise exception using errcode='42501',message='An active authorized account is required'; end if;
 if v_session is not null and not exists(select 1 from auth.sessions where id=v_session::uuid and user_id=v_actor) then
 raise exception using errcode='42501',message='Session has been revoked'; end if;
 return v_actor;
end $$;


ALTER FUNCTION private.require_actor(p_manager boolean) OWNER TO postgres;

--
-- Name: require_service(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.require_service() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
 and coalesce(current_setting('role',true),'')<>'service_role' then
 raise exception using errcode='42501',message='Service access required'; end if;
end $$;


ALTER FUNCTION private.require_service() OWNER TO postgres;

--
-- Name: required_fields(jsonb, text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.required_fields(p_payload jsonb, p_fields text[]) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare k text; begin
 foreach k in array p_fields loop if not (p_payload ? k) or p_payload->k='null'::jsonb or p_payload->>k='' then raise exception using errcode='22023',message='Required field: '||k; end if; end loop;
end $$;


ALTER FUNCTION private.required_fields(p_payload jsonb, p_fields text[]) OWNER TO postgres;

--
-- Name: service_core(text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.service_core(p_operation text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare b uuid; result jsonb;
begin
 perform private.require_service();
 if p_payload->>'actor_id' is not null then select branch_id into b from private.profiles where id=(p_payload->>'actor_id')::uuid;
 elsif p_payload->>'job_id' is not null then select branch_id into b from private.processing_jobs where id=(p_payload->>'job_id')::uuid;
 elsif p_payload->>'review_id' is not null then select branch_id into b from private.reviews where id=(p_payload->>'review_id')::uuid;
 elsif p_payload->>'menu_item_id' is not null then select branch_id into b from private.menu_items where id=(p_payload->>'menu_item_id')::uuid;
 elsif p_operation='review_submit' then select branch_id into b from private.review_tokens where token_hash=encode(extensions.digest(p_payload->>'token','sha256'),'hex');
 end if;
 perform set_config('app.branch_id',coalesce(b::text,''),true);
 result:=private.service_core_unscoped(p_operation,p_payload);
 return result;
end $$;


ALTER FUNCTION private.service_core(p_operation text, p_payload jsonb) OWNER TO postgres;

--
-- Name: service_core_unscoped(text, jsonb); Type: FUNCTION; Schema: private; Owner: sd_branch_executor
--

CREATE FUNCTION private.service_core_unscoped(p_operation text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_variable
declare actor uuid:=(p_payload->>'actor_id')::uuid; uid uuid:=(p_payload->>'user_id')::uuid; id uuid; prov private.user_provisioning;
 tok private.review_tokens; prof private.profiles; result jsonb; email text; fullname text;
begin
 perform private.require_service();
 if p_operation='health' then return jsonb_build_object('schema','smartdine','version',1,'ready',true); end if;
 if p_operation='bootstrap_manager' then
 perform pg_advisory_xact_lock(hashtextextended('smartdine:managers',0));
 if exists(select 1 from private.bootstrap_state) or exists(select 1 from private.profiles where role='manager' and is_active) then raise exception using errcode='40001',message='Manager has already been bootstrapped'; end if;
 select * into prof from private.profiles where profiles.id=uid for update;
 if not found then raise exception using errcode='22023',message='Provision the managed Auth user first'; end if;
 update private.profiles set role='manager',is_active=true,full_name=coalesce(nullif(p_payload->>'full_name',''),full_name),version=version+1,updated_at=now() where profiles.id=uid;
 insert into private.bootstrap_state(singleton) values(true);
 perform private.audit(uid,'bootstrap_manager','profiles',uid,to_jsonb(prof),(select to_jsonb(p) from private.profiles p where p.id=uid));
 return (select to_jsonb(p) from private.profiles p where p.id=uid);
 elsif p_operation in ('reserve_user','activate_user') then
 if actor is null or not exists(select 1 from private.profiles where profiles.id=actor and role='manager' and is_active) then raise exception using errcode='42501',message='Active manager required'; end if;
 if p_operation='reserve_user' then
 if coalesce(p_payload->>'role','staff')<>'staff' then raise exception using errcode='42501',message='Managers are provisioned by the database owner only';end if;
 email:=lower(btrim(p_payload->>'email')); fullname:=btrim(p_payload->>'full_name');
 if email is null or position('@' in email)<2 or fullname is null or length(fullname)=0 or length(coalesce(p_payload->>'request_key','')) not between 1 and 200 then raise exception using errcode='22023',message='Valid email, name and request key required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('provision:'||email,0));
 select * into prov from private.user_provisioning where requested_by=actor and request_key=p_payload->>'request_key';
 if found then
 if prov.email<>email or prov.full_name<>fullname or prov.role<>p_payload->>'role' or prov.staff_type<>coalesce(p_payload->>'staff_type','waiter') then raise exception using errcode='23505',message='Provisioning key payload conflict'; end if;
 return to_jsonb(prov);
 end if;
 if exists(select 1 from private.user_provisioning where user_provisioning.email=email) or exists(select 1 from private.profiles where profiles.email=email) then raise exception using errcode='23505',message='Email already exists or is being provisioned'; end if;
 insert into private.user_provisioning(email,full_name,role,requested_by,request_key,staff_type) values(email,fullname,p_payload->>'role',actor,p_payload->>'request_key',coalesce(p_payload->>'staff_type','waiter')) returning * into prov;
 return to_jsonb(prov);
 else
 select * into prov from private.user_provisioning where user_provisioning.id=(p_payload->>'provision_id')::uuid for update;
 if not found or prov.requested_by<>actor then raise exception using errcode='P0002',message='Provisioning request not found'; end if;
 if prov.role<>'staff' then raise exception using errcode='42501',message='Only staff provisioning is allowed';end if;
 if prov.status='active' then if prov.user_id<>uid then raise exception using errcode='23505',message='Provisioning user conflict'; end if; return (select to_jsonb(p) from private.profiles p where p.id=uid); end if;
 select * into prof from private.profiles where profiles.id=uid for update;
 if not found or lower(prof.email)<>prov.email then raise exception using errcode='22023',message='Auth user must match provisioning email'; end if;
 update private.profiles set branch_id=(select branch_id from private.profiles where profiles.id=actor),role=prov.role,staff_type=prov.staff_type,full_name=prov.full_name,is_active=true,version=version+1,updated_at=now() where profiles.id=uid;
 update private.user_provisioning set status='active',user_id=uid where user_provisioning.id=prov.id;
 result:=(select to_jsonb(p) from private.profiles p where p.id=uid); perform private.audit(actor,'activate_user','profiles',uid,to_jsonb(prof),result); return result;
 end if;
 elsif p_operation='review_submit' then
 select * into tok from private.review_tokens where token_hash=encode(extensions.digest(p_payload->>'token','sha256'),'hex') for update;
 if not found or tok.used_at is not null or tok.expires_at<=now() then raise exception using errcode='22023',message='Review token is invalid, expired or already used'; end if;
 if p_payload->>'menu_item_id' is not null and not exists(select 1 from private.order_items where order_id=tok.order_id and menu_item_id=(p_payload->>'menu_item_id')::uuid) then raise exception using errcode='22023',message='Review item was not purchased in this order'; end if;
 insert into private.reviews(order_id,menu_item_id,rating,comment) values(tok.order_id,(p_payload->>'menu_item_id')::uuid,(p_payload->>'rating')::int,p_payload->>'comment') returning reviews.id into id;
 update private.review_tokens set used_at=now() where review_tokens.id=tok.id;
 perform private.enqueue_job('review_analysis',jsonb_build_object('review_id',id),'review:'||id::text,null);
 perform private.audit(null,'review_submit','reviews',id,null,jsonb_build_object('id',id,'order_id',tok.order_id));
 return jsonb_build_object('id',id,'analysis_status','pending');
 else return private.json_decimals(private.service_intelligence(p_operation,p_payload)); end if;
end $$;


ALTER FUNCTION private.service_core_unscoped(p_operation text, p_payload jsonb) OWNER TO sd_branch_executor;

--
-- Name: service_intelligence(text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.service_intelligence(p_operation text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_job private.processing_jobs%rowtype;v_id uuid;v_token uuid;v_lease integer;
 v_result jsonb:=p_payload->'result';v_row jsonb;v_comment text;v_as_of date;v_start date;v_actor uuid;
 v_run private.assistant_runs%rowtype;v_review uuid;v_now timestamptz:=clock_timestamp();
begin
 perform private.require_service();
 case p_operation
 when 'job_claim' then
  v_lease:=coalesce((p_payload->>'lease_seconds')::integer,120);
  if v_lease not between 15 and 3600 then raise exception using errcode='22023',message='Invalid job lease';end if;
  -- Expired final attempts are terminal; they must not stay running forever.
  with expired as (
   update private.processing_jobs set status='failed',owner_token=null,lease_expires_at=null,last_error_code='LeaseExpired'
   where status='running' and lease_expires_at<=v_now and attempts>=max_attempts returning kind,payload
  ) update private.reviews set analysis_status='failed' where id in (select (payload->>'review_id')::uuid from expired where kind='review_analysis');
  select * into v_job from private.processing_jobs
   where attempts<max_attempts and ((status='queued' and available_at<=v_now) or (status='running' and lease_expires_at<=v_now))
   order by available_at,created_at,id for update skip locked limit 1;
  if not found then return null;end if;
  update private.processing_jobs set status='running',attempts=attempts+1,owner_token=gen_random_uuid(),lease_expires_at=v_now+make_interval(secs=>v_lease)
   where id=v_job.id returning * into v_job;
  return to_jsonb(v_job);
 when 'job_heartbeat' then
  v_lease:=coalesce((p_payload->>'lease_seconds')::integer,120);
  if v_lease not between 15 and 3600 then raise exception using errcode='22023',message='Invalid job lease';end if;
  update private.processing_jobs set lease_expires_at=v_now+make_interval(secs=>v_lease)
   where id=(p_payload->>'job_id')::uuid and status='running' and owner_token=(p_payload->>'owner_token')::uuid and lease_expires_at>v_now returning id into v_id;
  return jsonb_build_object('renewed',v_id is not null);
 when 'job_complete','job_fail' then
  select * into v_job from private.processing_jobs where id=(p_payload->>'job_id')::uuid for update;
  if not found or v_job.status<>'running' or v_job.owner_token is distinct from (p_payload->>'owner_token')::uuid or v_job.lease_expires_at<=clock_timestamp() then
   raise exception using errcode='40001',message='Job lease is no longer owned';end if;
  if p_operation='job_fail' then
   update private.processing_jobs set status=case when attempts>=max_attempts then 'failed' else 'queued' end,
    owner_token=null,lease_expires_at=null,last_error_code=left(coalesce(p_payload->>'error_code','ProcessingFailed'),120),
    available_at=clock_timestamp()+make_interval(secs=>least(900,5*(2^attempts)::integer)) where id=v_job.id;
   if v_job.kind='review_analysis' and v_job.attempts>=v_job.max_attempts then
    update private.reviews set analysis_status='failed' where id=(v_job.payload->>'review_id')::uuid;end if;
   return jsonb_build_object('job_id',v_job.id,'retrying',v_job.attempts<v_job.max_attempts);
  end if;
  if v_result is null or jsonb_typeof(v_result)<>'object' then raise exception using errcode='22023',message='Invalid job result';end if;
  if v_job.kind='review_analysis' then
   v_review:=(v_job.payload->>'review_id')::uuid;
   select comment into v_comment from private.reviews where id=v_review;
   if not found then raise exception using errcode='P0002',message='Review not found';end if;
   if jsonb_typeof(v_result->'aspects') is distinct from 'array' or jsonb_array_length(v_result->'aspects')>16
    or v_result->>'model' is null or v_result->>'prompt_version' is null then
    raise exception using errcode='22023',message='Invalid review analysis';end if;
   for v_row in select value from jsonb_array_elements(v_result->'aspects') loop
    if coalesce(v_row->>'aspect','') not in ('taste','price_value','service_speed','cleanliness')
     or coalesce(v_row->>'sentiment','') not in ('positive','neutral','negative','mixed')
     or coalesce(length(v_row->>'evidence'),0)=0 or (v_row->>'start')::integer<0
     or (v_row->>'end')::integer<>(v_row->>'start')::integer+length(v_row->>'evidence')
     or substring(v_comment from (v_row->>'start')::integer+1 for length(v_row->>'evidence')) is distinct from v_row->>'evidence' then
     raise exception using errcode='22023',message='Review evidence is not an exact original-text span';end if;
   end loop;
   insert into private.review_analyses(review_id,job_id,result,model,prompt_version)
    values(v_review,v_job.id,v_result,v_result->>'model',v_result->>'prompt_version');
   update private.reviews set analysis_status='completed' where id=v_review;
  elsif v_job.kind='forecast' then
   if v_result->>'status' not in ('completed','insufficient_history') or v_result->>'menu_item_id' is distinct from v_job.payload->>'menu_item_id' then
    raise exception using errcode='22023',message='Forecast does not match job';end if;
   insert into private.forecast_runs(job_id,menu_item_id,as_of,status,result)
    values(v_job.id,(v_job.payload->>'menu_item_id')::uuid,(v_job.payload->>'as_of')::date,v_result->>'status',v_result);
  end if;
  update private.processing_jobs set status='completed',result=v_result,completed_at=clock_timestamp(),owner_token=null,lease_expires_at=null where id=v_job.id;
  return jsonb_build_object('job_id',v_job.id,'status','completed');
 when 'review_analysis_input' then
  select jsonb_build_object('review_id',id,'comment',comment) into v_result from private.reviews where id=(p_payload->>'review_id')::uuid;
  if not found then raise exception using errcode='P0002',message='Review not found';end if;return v_result;
 when 'forecast_input' then
  v_id:=(p_payload->>'menu_item_id')::uuid;v_as_of:=(p_payload->>'as_of')::date;
  if v_id is null or v_as_of is null or not exists(select 1 from private.menu_items where id=v_id) then raise exception using errcode='22023',message='Invalid forecast input';end if;
  v_start:=(date_trunc('month',v_as_of::timestamp)-interval '6 months')::date;
  select coalesce(jsonb_agg(to_jsonb(q) order by q.day),'[]') into v_result from (
   select c.day,case when c.source='historical' then h.quantity else coalesce(s.quantity,0) end as quantity,true as covered
   from private.daily_coverage c
   left join private.historical_sales h on h.day=c.day and h.menu_item_id=v_id
   left join lateral(select sum(oi.quantity)::bigint as quantity from private.order_items oi join private.orders o on o.id=oi.order_id
    where oi.menu_item_id=v_id and o.status='completed' and (o.completed_at at time zone 'Asia/Karachi')::date=c.day) s on c.source='live'
   where c.day>=v_start and c.day<v_as_of and
    ((c.source='live' and c.day>=(select (created_at at time zone 'Asia/Karachi')::date from private.menu_items where id=v_id))
     or (c.source='historical' and h.menu_item_id is not null))
  ) q;
  return jsonb_build_object('menu_item_id',v_id,'rows',v_result);
 when 'assistant_start' then
  v_actor:=(p_payload->>'actor_id')::uuid;
  if not exists(select 1 from private.profiles where id=v_actor and is_active and role='manager') then raise exception using errcode='42501',message='Manager required';end if;
  insert into private.assistant_runs(id,actor_id,question,period,model,prompt_version)
   values((p_payload->>'run_id')::uuid,v_actor,p_payload->>'question',p_payload->'period',p_payload->>'model',p_payload->>'prompt_version');
  return jsonb_build_object('run_id',p_payload->>'run_id');
 when 'assistant_finish' then
  select * into v_run from private.assistant_runs where id=(p_payload->>'run_id')::uuid for update;
  if not found then raise exception using errcode='P0002',message='Assistant run not found';end if;
  if v_run.status<>'running' then raise exception using errcode='40001',message='Assistant run already finished';end if;
  if v_run.actor_id is distinct from (p_payload->>'actor_id')::uuid then raise exception using errcode='42501',message='Assistant actor mismatch';end if;
  if coalesce(p_payload->>'status','') not in ('completed','failed') then raise exception using errcode='22023',message='Invalid assistant status';end if;
  for v_row in select value from jsonb_array_elements(coalesce(p_payload->'evidence','[]')) loop
   if coalesce(v_row->>'tool','') not in ('sales_and_margins','inventory_status','customer_reviews','demand_forecasts','operating_expenses') then
    raise exception using errcode='22023',message='Unknown assistant evidence tool';end if;
   insert into private.assistant_evidence(run_id,evidence_id,tool,arguments,result)
    values(v_run.id,v_row->>'id',v_row->>'tool',v_row->'period',v_row->'data');
  end loop;
  if p_payload->>'status'='completed' and (v_result is null or jsonb_typeof(v_result->'evidence_ids') is distinct from 'array'
   or jsonb_array_length(v_result->'evidence_ids')<1 or exists(
    select 1 from jsonb_array_elements_text(v_result->'evidence_ids') e where not exists(
     select 1 from private.assistant_evidence a where a.run_id=v_run.id and a.evidence_id=e.value))) then
   raise exception using errcode='22023',message='Assistant citations must refer to recorded evidence';end if;
  update private.assistant_runs set status=p_payload->>'status',result=v_result,error_code=left(p_payload->>'error_code',120),completed_at=clock_timestamp() where id=v_run.id;
  perform private.audit(v_run.actor_id,'assistant_'||(p_payload->>'status'),'assistant_runs',v_run.id,null,jsonb_build_object('model',v_run.model));
  return jsonb_build_object('run_id',v_run.id,'status',p_payload->>'status');
 else raise exception using errcode='22023',message='Unknown service operation';
 end case;
end $$;


ALTER FUNCTION private.service_intelligence(p_operation text, p_payload jsonb) OWNER TO postgres;

--
-- Name: set_order_items(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.set_order_items(p_id uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare item jsonb; m private.menu_items; q integer; old_prices jsonb;
begin
 if jsonb_typeof(p_items) is distinct from 'array' then raise exception using errcode='22023',message='Order items array required'; end if;
 if jsonb_array_length(p_items) not between 1 and 100 then raise exception using errcode='22023',message='Order must contain 1 to 100 items'; end if;
 select coalesce(jsonb_object_agg(menu_item_id::text,price_snapshot),'{}') into old_prices from private.order_items where order_id=p_id;
 delete from private.order_items where order_id=p_id;
 for item in select value from jsonb_array_elements(p_items) loop
 select * into m from private.menu_items where id=(item->>'menu_item_id')::uuid and is_active for share;
 if not found then raise exception using errcode='22023',message='Menu item is unavailable'; end if;
 q:=(item->>'quantity')::integer;
 insert into private.order_items(order_id,menu_item_id,name_snapshot,quantity,price_snapshot)
 values(p_id,m.id,m.name,q,coalesce((old_prices->>m.id::text)::numeric,m.selling_price));
 end loop;
end $$;


ALTER FUNCTION private.set_order_items(p_id uuid, p_items jsonb) OWNER TO postgres;

--
-- Name: set_recipe(uuid, jsonb, integer, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.set_recipe(p_id uuid, p_ingredients jsonb, p_expected integer, p_actor uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare m private.menu_items; item jsonb;
begin
 select * into m from private.menu_items where id=p_id and deleted_at is null for update;
 if not found then raise exception using errcode='P0002',message='Menu item not found'; end if;
 perform private.expect_version(m.version,p_expected);
 if jsonb_typeof(p_ingredients) is distinct from 'array' then raise exception using errcode='22023',message='Recipe ingredients array required'; end if;
 if jsonb_array_length(p_ingredients) not between 1 and 100 then raise exception using errcode='22023',message='Recipe must contain 1 to 100 ingredients'; end if;
 delete from private.recipes where menu_item_id=p_id;
 for item in select value from jsonb_array_elements(p_ingredients) loop
 if not exists(select 1 from private.ingredients where id=(item->>'ingredient_id')::uuid and is_active) then raise exception using errcode='22023',message='Recipe ingredient is unavailable'; end if;
 insert into private.recipes(menu_item_id,ingredient_id,quantity) values(p_id,(item->>'ingredient_id')::uuid,(item->>'quantity')::numeric);
 end loop;
 update private.menu_items set version=version+1,updated_at=now() where id=p_id;
 perform private.audit(p_actor,'recipe_set','menu_items',p_id,to_jsonb(m),p_ingredients);
end $$;


ALTER FUNCTION private.set_recipe(p_id uuid, p_ingredients jsonb, p_expected integer, p_actor uuid) OWNER TO postgres;

--
-- Name: staff_json(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.staff_json(p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare k text; v jsonb; r jsonb; begin
 if jsonb_typeof(p_value)='array' then select coalesce(jsonb_agg(private.staff_json(value)),'[]') into r from jsonb_array_elements(p_value); return r;
 elsif jsonb_typeof(p_value)='object' then r:='{}'; for k,v in select * from jsonb_each(p_value) loop
 if k<>all(array['ingredient_cost_snapshot','packaging_cost_snapshot','fee_allocated','recipe_version','average_unit_cost','unit_cost','value','platform_fee','delivery_cost','packaging_cost']) then r:=r||jsonb_build_object(k,private.staff_json(v)); end if;
 end loop; return r;
 end if; return p_value; end $$;


ALTER FUNCTION private.staff_json(p_value jsonb) OWNER TO postgres;

--
-- Name: sync_auth_account(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sync_auth_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if new.email is distinct from old.email or new.encrypted_password is distinct from old.encrypted_password then
   update private.profiles set email=lower(new.email),version=version+1,updated_at=now() where id=new.id;
   delete from auth.sessions where user_id=new.id;
   perform private.audit(null,'account_credentials_changed','profiles',new.id,null,
     jsonb_build_object('email_changed',new.email is distinct from old.email,'password_changed',new.encrypted_password is distinct from old.encrypted_password));
 end if;
 return new;
end $$;


ALTER FUNCTION private.sync_auth_account() OWNER TO postgres;

--
-- Name: validate_managed_user(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_managed_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into private.profiles(id,email,full_name,role,is_active)
 values(new.id,lower(new.email),coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'Pending account'),'staff',false);
 return new;
end $$;


ALTER FUNCTION private.validate_managed_user() OWNER TO postgres;

--
-- Name: validate_payload(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.validate_payload(p_value jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare k text; v jsonb; begin
 if jsonb_typeof(p_value)='array' then for v in select value from jsonb_array_elements(p_value) loop perform private.validate_payload(v); end loop;
 elsif jsonb_typeof(p_value)='object' then for k,v in select * from jsonb_each(p_value) loop
 if k=any(array['selling_price','packaging_cost','discount','platform_fee','delivery_cost','tax','amount','quantity','unit_cost','reorder_level']) then
 if v='null'::jsonb or jsonb_typeof(v) not in ('number','string') or (v#>>'{}')!~'^-?[0-9]+([.][0-9]+)?$' then raise exception using errcode='22023',message='Finite decimal value required for '||k; end if;
 end if;
 perform private.validate_payload(v);
 end loop; end if;
end $_$;


ALTER FUNCTION private.validate_payload(p_value jsonb) OWNER TO postgres;

