ALTER TABLE public.orders OWNER TO postgres;

--
-- Name: recipe_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.recipe_items (
    menu_item_id uuid NOT NULL,
    ingredient_id uuid NOT NULL,
    quantity numeric(12,3) NOT NULL,
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_recipe_items_quantity_positive CHECK ((quantity > (0)::numeric))
);


ALTER TABLE public.recipe_items OWNER TO postgres;

--
-- Name: recommendations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.recommendations (
    title character varying(200) NOT NULL,
    category character varying(50) NOT NULL,
    evidence json NOT NULL,
    proposed_action text NOT NULL,
    expected_impact text NOT NULL,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    decision_notes text,
    decided_by_id uuid,
    decided_at timestamp with time zone,
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.recommendations OWNER TO postgres;

--
-- Name: review_tokens; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.review_tokens (
    token_hash character varying(64) NOT NULL,
    order_id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    is_used boolean DEFAULT false NOT NULL,
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.review_tokens OWNER TO postgres;

--
-- Name: reviews; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.reviews (
    order_id uuid,
    token_id uuid,
    rating integer NOT NULL,
    comment text NOT NULL,
    sentiment character varying(20) NOT NULL,
    aspects json DEFAULT '[]'::json NOT NULL,
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_reviews_review_rating_range CHECK (((rating >= 1) AND (rating <= 5)))
);


ALTER TABLE public.reviews OWNER TO postgres;

--
-- Name: users; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.users (
    email character varying(320) NOT NULL,
    full_name character varying(120) NOT NULL,
    hashed_password character varying(255) NOT NULL,
    role character varying(7) NOT NULL,
    is_active boolean NOT NULL,
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_users_user_role CHECK (((role)::text = ANY ((ARRAY['manager'::character varying, 'staff'::character varying])::text[])))
);


ALTER TABLE public.users OWNER TO postgres;

