--
-- Name: assistant_evidence branch_isolation; Type: POLICY; Schema: private; Owner: postgres
--

CREATE POLICY branch_isolation ON private.assistant_evidence TO sd_branch_executor USING (((branch_id = private.current_branch()) OR ((((NULLIF(current_setting('request.jwt.claims'::text, true), ''::text))::jsonb ->> 'role'::text) = 'service_role'::text) AND (private.current_branch() IS NULL)))) WITH CHECK (((branch_id = private.current_branch()) OR ((((NULLIF(current_setting('request.jwt.claims'::text, true), ''::text))::jsonb ->> 'role'::text) = 'service_role'::text) AND (private.current_branch() IS NULL))));


